  "p208": {"q":"解析說「蒙」的讀音怎麼分？","o":["都讀ㄇㄥˇ","蒙蔽讀ㄇㄥˇ","都讀ㄇㄥˋ","一般讀ㄇㄥˊ（蒙蔽、啟蒙）；「蒙古」讀ㄇㄥˇ"],"a":3},
  "p209": {"q":"依解析，「荷」的兩個讀音怎麼分？","o":["植物義讀二聲（荷花）；扛擔義讀四聲（負荷、荷槍）","都讀二聲","都讀四聲","荷花讀四聲"],"a":0},
